namespace {
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
bool blue(const QColor& c){return c.red()>=35&&c.red()<110&&c.green()>=75&&c.green()<150&&c.blue()>=145&&c.blue()<210&&c.blue()>c.green()+30;}
bool purple(const QColor& c){return c.red()>=90&&c.red()<155&&c.green()>=70&&c.green()<125&&c.blue()>130&&c.blue()<195&&c.blue()>c.green()+25;}
bool anyBlue(const QColor& c){return c.blue()>c.red()+40&&c.blue()>c.green()+20;}
bool red(const QColor& c){return c.red()>140&&c.red()>c.green()+50&&c.red()>c.blue()+25;}
int count(const QImage& image,const QRect& rect,bool (*color)(const QColor&)){int value=0;for(int y=std::max(0,rect.top());y<=std::min(image.height()-1,rect.bottom());++y)for(int x=std::max(0,rect.left());x<=std::min(image.width()-1,rect.right());++x)if(color(image.pixelColor(x,y)))++value;return value;}
struct Fixture{WorkbookSession session;WorksheetModel model{session};QWidget window;FormulaLineEdit bar{&window};WorksheetView view{&window};Fixture(){auto* row=new QVBoxLayout(&window);row->addWidget(&bar);row->addWidget(&view);view.setModel(&model);view.setFormulaBar(&bar);view.editorFactory=[](QWidget* parent){return new FormulaLineEdit(parent);};window.resize(820,560);window.show();window.activateWindow();QApplication::processEvents();view.setCurrentIndex(model.index(0,3));}~Fixture(){view.cancelEntry();}};
QRect edge(Fixture& f,int col){auto r=f.view.visualRect(f.model.index(0,col));r.setWidth(3);return r.adjusted(0,3,0,-3);}
void ready(){Fixture f;require(f.model.setData(f.model.index(0,3),"=AVERAGE(B1:B3)",Qt::EditRole),"seed source average formula");f.view.setFocus();QTest::mouseClick(f.view.viewport(),Qt::LeftButton,Qt::NoModifier,f.view.visualRect(f.model.index(0,3)).center());QApplication::processEvents();const auto before=f.session.snapshot();auto r=f.view.visualRect(f.model.index(0,1)).united(f.view.visualRect(f.model.index(2,1)));require(count(f.view.viewport()->grab().toImage(),r,anyBlue)==0,"Ready selected formula has no precedent outlines, as source48:06");f.view.edit(f.model.index(0,3));QApplication::processEvents();auto* editor=f.view.activeCellEditor();require(editor,"F2-style editing opens the native formula editor");QTest::keyClick(editor,Qt::Key_End);QApplication::processEvents();require(count(f.view.viewport()->grab().toImage(),r,blue)>20,"editing the selected formula reveals its source-blue precedent range");f.view.cancelEntry();QApplication::processEvents();require(count(f.view.viewport()->grab().toImage(),r,anyBlue)==0&&f.session.snapshot()==before,"Escape returns to Ready with no precedent outlines or canonical change");}
void palette(){Fixture f;f.bar.setFocus();QTest::keyClicks(&f.bar,"=B1+C1+B1+A3");QApplication::processEvents();const auto before=f.session.snapshot();const auto image=f.view.viewport()->grab().toImage();require(count(image,edge(f,1),blue)>8,"repeated references keep the source first-reference blue instead of being recolored per occurrence");require(count(image,edge(f,2),red)>8,"the second distinct reference uses source red rather than green");auto third=f.view.visualRect(f.model.index(2,0));third.setWidth(3);require(count(image,third.adjusted(0,3,0,-3),purple)>8,"the third distinct reference uses the source muted purple hue");require(f.session.snapshot()==before,"reference colors are presentation without workbook edits");}
void text(){QWidget host;auto* row=new QVBoxLayout(&host);FormulaLineEdit editor;QLineEdit other;row->addWidget(&editor);row->addWidget(&other);host.resize(600,120);host.show();host.activateWindow();editor.setFont(QFont("Calibri",14));editor.setFocus();QTest::keyClicks(&editor,"=-F28*F15");QApplication::processEvents();const auto raw=editor.text();const auto cursor=editor.cursorPosition();const auto image=editor.grab().toImage();require(count(image,image.rect(),blue)>8&&count(image,image.rect(),red)>8,"active formula editor paints source-blue and source-red reference text");require(editor.text()==raw&&editor.cursorPosition()==cursor&&!editor.hasSelectedText(),"color painting preserves the native draft and caret");editor.selectAll();QApplication::processEvents();require(editor.selectedText()==raw,"native formula text selection remains intact");QTest::keyClick(&editor,Qt::Key_End);QTest::keyClick(&editor,Qt::Key_Left);QTest::keyClicks(&editor,"0");require(editor.text()=="=-F28*F105","native text insertion still edits exactly at the caret");editor.undo();require(editor.text()==raw,"native QLineEdit undo remains available");other.setFocus();QApplication::processEvents();const auto mirror=editor.grab().toImage();require(count(mirror,mirror.rect(),blue)==0&&count(mirror,mirror.rect(),red)==0,"unfocused mirrored formula text stays black, as source48:04 and49:12");}
void expansion(){Fixture f;const auto target=f.model.index(3,3);const QString formula="=IF(B1<0,-B1,-B1*$C$1)";require(f.model.setData(target,formula,Qt::EditRole),"seed observed long IF formula");require(f.model.apply(Json::array({{{"type","set_style"},{"sheet",f.model.sheetId().toStdString()},{"row",4},{"col",4},{"style",{{"alignment","right"}}}}})),"prepare right-aligned numeric result style");f.view.setCurrentIndex(target);f.view.setFocus();const auto before=f.session.snapshot();f.view.edit(target);QApplication::processEvents();auto* editor=f.view.activeCellEditor();require(editor,"actual in-cell editor opens for the IF formula");QTest::keyClick(editor,Qt::Key_End);QApplication::processEvents();const int required=editor->fontMetrics().horizontalAdvance(formula)+4;require(editor->alignment()&Qt::AlignLeft,"formula editor uses source left alignment independently of its result format");require(editor->width()>=required&&editor->geometry().right()<f.view.viewport()->width(),"source long formula editor expands across neighboring cells to show the full formula within its viewport");if(const auto path=qEnvironmentVariable("TIGERSHEETS_FORMULA_SOURCE_CAPTURE");!path.isEmpty())require(f.window.grab().save(path),"retain actual native formula editing pixels");QTest::keyClicks(editor,"+B1");require(editor->width()>=editor->fontMetrics().horizontalAdvance(editor->text())+4,"the native formula editor grows while the draft is typed");f.view.cancelEntry();require(f.session.snapshot()==before,"editor expansion and cancellation leave native workbook data unchanged");require(f.model.setData(target,"ordinary long text that exceeds the source cell",Qt::EditRole),"prepare ordinary value editing");f.view.edit(target);QApplication::processEvents();require(f.view.activeCellEditor()&&f.view.activeCellEditor()->width()<=f.view.visualRect(target).width(),"normal value editing keeps its original native geometry");f.view.cancelEntry();require(f.model.setData(target,"="+QString("B1+").repeated(100)+"C1",Qt::EditRole),"prepare a formula wider than the viewport");f.view.edit(target);QApplication::processEvents();editor=f.view.activeCellEditor();QTest::keyClick(editor,Qt::Key_End);QApplication::processEvents();require(editor->width()>f.view.visualRect(target).width()&&editor->geometry().right()<f.view.viewport()->width(),"long native formula editing grows to the viewport boundary and wraps the remaining draft");f.view.cancelEntry();}
bool ink(const QColor& color){return std::min({color.red(),color.green(),color.blue()})<150;}
void shortFormulaKeepsItsClosingParenthesisOnOneLine(){
 Fixture f;const auto target=f.model.index(32,2);const QString formula="=SUM(C27:C32)";require(f.model.setData(target,formula,Qt::EditRole),"seed a short SUM draft");require(f.model.apply(Json::array({{{"type","set_style"},{"sheet",f.model.sheetId().toStdString()},{"row",33},{"col",3},{"style",{{"fontSize",12},{"fontFamily","Calibri"},{"bold",true}}}},{{"type","set_sheet_layout"},{"sheet",f.model.sheetId().toStdString()},{"defaultRowHeight",15.75}}})),"use worksheet font metrics and compact source rows");f.view.setColumnWidth(0,19);f.view.setColumnWidth(1,245);f.view.setColumnWidth(2,83);f.view.setShowGrid(false);f.view.setCurrentIndex(target);f.view.scrollTo(target,QAbstractItemView::PositionAtCenter);f.view.setFocus();QApplication::processEvents();const auto before=f.session.snapshot();f.view.edit(target);QApplication::processEvents();auto* editor=f.view.activeCellEditor();require(editor,"the short SUM opens a real inline editor");QTest::keyClick(editor,Qt::Key_End);QApplication::processEvents();
 require(!editor->property("formula.softWrap").toBool()&&editor->height()<=f.view.rowHeight(target.row())+2,"a short formula that fits the viewport keeps its closing parenthesis on the same native editor line");QTextLayout layout(formula,editor->font());layout.beginLayout();auto first=layout.createLine();first.setLineWidth(editor->width()-4);auto second=layout.createLine();layout.endLayout();require(first.textLength()==formula.size()&&!second.isValid(),"the actual glyph layout fits the entire short formula inside its expanded editor");f.view.cancelEntry();require(f.session.snapshot()==before,"formula layout does not change stored input or history");
}
void wrapping(bool caretBlink=false,bool externalBlack=false){
 for(const int column:{2,3}){Fixture f;if(caretBlink)QApplication::setCursorFlashTime(160);f.window.resize(1280,720);QApplication::processEvents();f.window.resize(f.window.width()+1230-f.view.viewport()->width(),720);QApplication::processEvents();require(f.view.viewport()->width()==1230,"source viewport width is exactly1230px");const auto target=f.model.index(column==2?29:40,column);const QString source="'[Otis-10-K-Raw.xls]consolidated balance sheets'!";const QString formula="="+source+(column==2?"B15":"B29")+"+"+source+(column==2?"B17":"B31")+"+"+source+(column==2?"B18":"B32");require(f.model.setData(target,formula,Qt::EditRole),"seed observed three-part external formula");require(f.model.apply(Json::array({{{"type","set_style"},{"sheet",f.model.sheetId().toStdString()},{"row",target.row()+1},{"col",column+1},{"style",{{"fontSize",12},{"alignment","right"}}}},{{"type","set_sheet_layout"},{"sheet",f.model.sheetId().toStdString()},{"defaultRowHeight",15.75}}})),"prepare source12pt font and21px rows");f.view.setColumnWidth(0,19);f.view.setColumnWidth(1,215);for(int col=2;col<16;++col)f.view.setColumnWidth(col,83);f.view.setCurrentIndex(target);f.view.scrollTo(target,QAbstractItemView::PositionAtCenter);f.view.setFocus();QApplication::processEvents();const auto before=f.session.snapshot();f.view.edit(target);QApplication::processEvents();auto* editor=f.view.activeCellEditor();require(editor,"source inline formula editor opens");QTest::keyClick(editor,Qt::Key_End);QApplication::processEvents();const auto normalFace=QFontInfo(QFont(QFontDatabase::families().contains("Calibri",Qt::CaseInsensitive)?"Calibri":"Helvetica",12)).family();require(f.model.cellStyle(target.row(),target.column()).value("fontFamily",std::string("Calibri"))=="Calibri"&&editor->font().pointSizeF()==12&&QFontInfo(editor->font()).family()==normalFace,"inline formula preserves the edited cell Calibri12 declaration and uses its resolved worksheet presentation rather than application chrome font");const int rowPitch=f.view.rowHeight(target.row());const int pitch=std::max(rowPitch,QFontMetrics(QFont(normalFace,12)).height()+2);std::cerr<<"Wrapped source editor "<<editor->width()<<'x'<<editor->height()<<" rowPitch="<<rowPitch<<" editorPitch="<<pitch<<" required="<<editor->fontMetrics().horizontalAdvance(formula)<<'\n';require(rowPitch==21&&editor->property("formula.linePitch").toInt()==pitch&&editor->height()==2*pitch,"source formulas retain21px worksheet rows and two legible native lines using the independently resolved worksheet font metrics");require(editor->geometry().right()<f.view.viewport()->width()&&editor->geometry().bottom()<f.view.viewport()->height(),"wrapped inline formula stays inside its real worksheet viewport");const auto image=editor->grab().toImage();if(externalBlack)require(count(image,image.rect(),blue)==0&&count(image,image.rect(),red)==0&&count(image,image.rect(),purple)==0,"source1130.5 and1356 external workbook references remain black in the focused wrapped editor");require(count(image,QRect(2,1,image.width()-4,pitch-2),ink)>40&&count(image,QRect(2,pitch,image.width()-4,pitch-2),ink)>15,"both source formula lines actually paint text");require(editor->text()==formula&&editor->cursorPosition()==formula.size()&&!editor->hasSelectedText()&&f.session.snapshot()==before,"soft wrapping preserves native draft/caret and workbook history");QTest::mouseClick(editor,Qt::LeftButton,Qt::NoModifier,QPoint(3,pitch+pitch/2));require(editor->cursorPosition()>formula.size()/2&&editor->cursorPosition()<formula.size(),"clicking the second rendered line places the actual native caret in that line");std::cerr<<"Second-line native caret="<<editor->cursorPosition()<<" suffix="<<formula.mid(editor->cursorPosition()).toStdString()<<'\n';if(QFontDatabase::families().contains("Calibri",Qt::CaseInsensitive))require(formula.mid(editor->cursorPosition()).startsWith(column==2?QString("sheets"):QString("Raw.xls")),"installed Calibri retains the source-observed second-line word-wrap break");else{QTextLayout expected(formula,QFont(normalFace,12));QTextOption option;option.setWrapMode(QTextOption::WrapAtWordBoundaryOrAnywhere);expected.setTextOption(option);expected.beginLayout();auto first=expected.createLine();first.setLineWidth(editor->width()-4);auto second=expected.createLine();second.setLineWidth(editor->width()-4);expected.endLayout();require(second.isValid()&&editor->cursorPosition()==second.textStart(),"accepted Helvetica fallback hit-testing reaches the independently laid-out second-line text boundary");}editor->selectAll();require(editor->selectedText()==formula,"native selection still contains exact unbroken formula text");QTest::keyClick(editor,Qt::Key_End);QTest::keyClicks(editor,"+1");require(editor->text()==formula+"+1","native typing appends at the wrapped caret");editor->undo();require(editor->text()==formula,"native QLineEdit Undo reverses the exact insertion");if(caretBlink){const auto visible=editor->grab().toImage();require(QTest::qWaitFor([&]{return editor->grab().toImage()!=visible;},500),"wrapped native caret retains blinking instead of remaining permanently painted");}if(const auto path=qEnvironmentVariable("TIGERSHEETS_FORMULA_WRAP_CAPTURE");!path.isEmpty())require(f.window.grab().save(path+QString(column==2?"-C30.png":"-D41.png")),"retain actual wrapped editing pixels");f.view.cancelEntry();require(f.session.snapshot()==before,"Escape from a wrapped formula preserves stored input and history");if(column==3){f.view.edit(target);QApplication::processEvents();editor=f.view.activeCellEditor();QTest::keyClick(editor,Qt::Key_End);QTest::keyClicks(editor,"+1");QTest::keyClick(editor,Qt::Key_Return);QApplication::processEvents();require(f.model.raw(target.row(),target.column())==formula+"+1"&&f.session.undo()&&f.session.snapshotView().at("sheets")==before.at("sheets"),"Enter commits a wrapped draft with one exact native Undo");}
 }
}
void externalText(){wrapping(false,true);FormulaLineEdit editor;editor.setFont(QFont("Calibri",12));editor.resize(1200,26);editor.show();editor.setFocus();QTest::keyClicks(&editor,"='[Source.xlsx]Sheet1'!A1");QApplication::processEvents();auto image=editor.grab().toImage();const auto textArea=editor.rect().adjusted(5,4,-5,-4);require(count(image,textArea,blue)==0&&count(image,textArea,red)==0&&count(image,textArea,purple)==0,"focused single-line external references retain black text");editor.selectAll();QTest::keyClicks(&editor,"=B1+C1");QApplication::processEvents();image=editor.grab().toImage();require(count(image,textArea,blue)>8&&count(image,textArea,red)>8&&count(image,textArea,purple)==0,"local references retain their source-blue/source-red text after editing an external formula");}
void handles(){Fixture f;f.bar.setFocus();QTest::keyClicks(&f.bar,"=B1+C1");QApplication::processEvents();const auto rect=f.view.visualRect(f.model.index(0,1));const auto image=f.view.viewport()->grab().toImage();require(blue(image.pixelColor(rect.topLeft()+QPoint(3,3))),"draft reference ranges show a filled source corner resize handle beyond the two-pixel range edge");}
void fills(){Fixture f;const auto before=f.session.snapshot();f.bar.setFocus();QTest::keyClicks(&f.bar,"=B1+C1");QApplication::processEvents();auto image=f.view.viewport()->grab().toImage();const auto first=f.view.visualRect(f.model.index(0,1)).center(),second=f.view.visualRect(f.model.index(0,2)).center();const auto a=image.pixelColor(first),b=image.pixelColor(second);require(a.red()>220&&a.blue()>a.red()+8&&b.green()>220&&b.red()>b.green()+8,"active source references have faint blue/red background fills behind their cell content");f.view.cancelEntry();QApplication::processEvents();image=f.view.viewport()->grab().toImage();require(image.pixelColor(first)==QColor(Qt::white)&&image.pixelColor(second)==QColor(Qt::white)&&f.session.snapshot()==before,"Ready clears transient reference fills without changing stored styles");}
void help(){FormulaLineEdit editor;editor.setFunctionCatalog({{"entries",Json::array({{{"name","AVERAGE"}},{{"name","IF"}}})}},{{"functions",{"AVERAGE","IF"}}});editor.resize(620,26);editor.move(80,80);editor.show();editor.setFocus();QTest::keyClicks(&editor,"=AVERAGE(B1:B3");QApplication::processEvents();auto* tip=editor.findChild<QLabel*>("formula.argumentHelp");if(tip)std::cerr<<"Call tooltip visible="<<tip->isVisible()<<" size="<<tip->width()<<"x"<<tip->height()<<" compact="<<tip->property("formula.compactCall").toBool()<<" text="<<tip->text().toStdString()<<'\n';require(tip&&tip->isVisible()&&tip->height()<=20&&!tip->text().contains("<br>"),"active source function-call tooltip is one compact signature line about18pixels high");if(const auto path=qEnvironmentVariable("TIGERSHEETS_CALL_SOURCE_CAPTURE");!path.isEmpty())require(tip->grab().save(path),"retain actual compact call tooltip pixels");require(editor.argumentHelpText().contains("arithmetic mean")&&editor.argumentHelpText().contains("<b>number1</b>"),"the full catalog help API retains its description and highlighted argument");require(tip->mapToGlobal(QPoint()).y()>=editor.mapToGlobal(QPoint(0,editor.height())).y()&&tip->mapToGlobal(QPoint()).y()<=editor.mapToGlobal(QPoint(0,editor.height()+2)).y(),"source compact signature sits immediately beneath the active editor");editor.selectAll();QTest::keyClicks(&editor,"=av");QApplication::processEvents();require(editor.completionPopup()->isVisible()&&tip->text().contains("arithmetic mean")&&!tip->text().contains("<br>")&&tip->height()<=22&&editor.argumentHelpText().contains("AVERAGE("),"autocomplete displays the complete description on one compact line while the full assistance API retains the signature");editor.selectAll();QTest::keyClicks(&editor,"=IF(B1<0,-B1,-B1*C1");QApplication::processEvents();require(tip->text().contains("[value_if_true]")&&tip->text().contains("<b>[value_if_false]</b>")&&tip->height()<=20,"source IF signature preserves optional argument brackets and highlights the active third parameter");const auto before=editor.text();QTest::keyClick(&editor,Qt::Key_Escape);require(!tip->isVisible()&&editor.argumentHelpText().isEmpty()&&editor.text()==before,"Escape dismisses compact assistance without changing the formula draft");}
}
int main(int argc,char** argv){QApplication app(argc,argv);try{const std::string mode=argc>1?argv[1]:"";if(mode=="short_formula")shortFormulaKeepsItsClosingParenthesisOnOneLine();else if(mode=="palette")palette();else if(mode=="text")text();else if(mode=="expansion")expansion();else if(mode=="wrap")wrapping();else if(mode=="wrap_caret")wrapping(true);else if(mode=="external_text")externalText();else if(mode=="handles")handles();else if(mode=="fills")fills();else if(mode=="help")help();else{shortFormulaKeepsItsClosingParenthesisOnOneLine();ready();}std::cout<<"Source formula presentation passed\n";}catch(const std::exception& e){std::cerr<<"FAILED: "<<e.what()<<'\n';return 1;}}
